## Corrected Full Code (AP-Aligned)
This fixes the earlier mistake of returning null (per your problem statement, we return an empty list for no path) and highlights all the key steps we discussed:

```java
import java.util.ArrayList;
import java.util.List;

// Given Point class (for reference)
class Point {
    public final int row, col;
    public Point(int row, int col) { this.row = row; this.col = col; }
    @Override public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Point p)) return false;
        return row == p.row && col == p.col;
    }
    @Override public int hashCode() { return 31 * row + col; }
}

public class MazeSolver {

    // Part A: Recursive backtracking to find all paths
    public static void findAllPaths(int[][] maze, int row, int col,
                                    List<Point> currentPath,
                                    List<List<Point>> allPaths) {

        // --------------------------
        // Step 1: All base cases FIRST (no adds yet!)
        // --------------------------
        // Out of bounds: invalid, return immediately
        if (row < 0 || row >= maze.length || col < 0 || col >= maze[0].length) {
            return;
        }

        // Wall or already visited: invalid, return immediately
        if (maze[row][col] == 1 || maze[row][col] == 4) {
            return;
        }

        // Reached end: save the full path
        if (maze[row][col] == 3) {
            currentPath.add(new Point(row, col)); // Add end cell temporarily
            allPaths.add(new ArrayList<>(currentPath)); // Save COPY of path state
            currentPath.remove(currentPath.size() - 1); // Backtrack end cell
            return;
        }

        // --------------------------
        // Step 2: Choose (mark as visited, add to path)
        // --------------------------
        int originalValue = maze[row][col];
        maze[row][col] = 4; // Mark as visited (temporary)
        currentPath.add(new Point(row, col));

        // --------------------------
        // Step 3: Explore all 4 directions
        // --------------------------
        findAllPaths(maze, row - 1, col, currentPath, allPaths); // Up
        findAllPaths(maze, row + 1, col, currentPath, allPaths); // Down
        findAllPaths(maze, row, col - 1, currentPath, allPaths); // Left
        findAllPaths(maze, row, col + 1, currentPath, allPaths); // Right

        // --------------------------
        // Step 4: Unchoose (restore state, remove from path)
        // --------------------------
        currentPath.remove(currentPath.size() - 1);
        maze[row][col] = originalValue; // Restore original maze value (no side effects!)
    }

    // Part B: Find shortest path
    public static List<Point> findShortestPath(int[][] maze) {
        // Step 1: Locate start cell (value 2)
        int startRow = -1, startCol = -1;
        for (int r = 0; r < maze.length; r++) {
            for (int c = 0; c < maze[0].length; c++) {
                if (maze[r][c] == 2) {
                    startRow = r;
                    startCol = c;
                    break;
                }
            }
            if (startRow != -1) break;
        }

        // Step 2: Initialize collections for backtracking
        List<Point> currentPath = new ArrayList<>();
        List<List<Point>> allPaths = new ArrayList<>();

        // Step 3: Run backtracking from start
        findAllPaths(maze, startRow, startCol, currentPath, allPaths);

        // Step 4: Return shortest path (or empty list if none)
        if (allPaths.isEmpty()) {
            return new ArrayList<>(); // Per problem statement: never return null
        }

        List<Point> shortest = allPaths.get(0);
        for (List<Point> path : allPaths) {
            if (path.size() < shortest.size()) {
                shortest = path;
            }
        }
        return shortest;
    }
}
```

