## Complete Recursive Java Code
```java
public class PathFinder {
    // Max time needed for 8x8 grid: 3 waits for temp obstacles + 8+8=16 steps to cross + buffer
    private static final int MAX_TIME = 30;
    // 4 movement directions: up, down, left, right
    private static final int[][] DIRECTIONS = {{-1,0}, {1,0}, {0,-1}, {0,1}};

    public static int findMinimumSteps(int[][] grid) {
        // Edge case: empty grid
        if (grid == null || grid.length == 0 || grid[0].length == 0) return -1;
        int rows = grid.length;
        int cols = grid[0].length;

        // 3D visited array to avoid reprocessing the same (row, col, time) state
        boolean[][][] visited = new boolean[rows][cols][MAX_TIME];

        // Start recursion from (0,0) at time 0
        int minSteps = findPath(grid, 0, 0, 0, visited, rows, cols);

        // Return -1 if no valid path exists, else return min steps
        return minSteps >= MAX_TIME ? -1 : minSteps;
    }

    // Recursive helper matching the skeleton you showed!
    private static int findPath(int[][] grid, int row, int col, int time, 
                                boolean[][][] visited, int rows, int cols) {
        // -------------------------- BASE CASES --------------------------
        // 1. Out of grid bounds → invalid path
        if (row < 0 || row >= rows || col < 0 || col >= cols) {
            // Use half of MAX_INT to avoid overflow when adding 1 later
            return Integer.MAX_VALUE / 2;
        }

        // 2. Permanent obstacle → invalid
        if (grid[row][col] == 1) {
            return Integer.MAX_VALUE / 2;
        }

        // 3. Temporary obstacle that hasn't disappeared yet → invalid
        if (grid[row][col] == 2 && time < 3) {
            return Integer.MAX_VALUE / 2;
        }

        // 4. SUCCESS: Reached the destination! No more steps needed
        if (row == rows - 1 && col == cols - 1) {
            return 0;
        }

        // 5. Already processed this state, or exceeded max time → no need to redo work
        if (time >= MAX_TIME || visited[row][col][time]) {
            return Integer.MAX_VALUE / 2;
        }

        // -------------------------- RECURSIVE STEP --------------------------
        // Mark this state as visited so we never process it again
        visited[row][col][time] = true;

        int minStepsFromHere = Integer.MAX_VALUE / 2;

        // First: try all 4 movement directions
        for (int[] dir : DIRECTIONS) {
            int newRow = row + dir[0];
            int newCol = col + dir[1];
            int newTime = time + 1;

            // Recursively get steps needed from the new position
            int stepsForThisPath = findPath(grid, newRow, newCol, newTime, visited, rows, cols);
            // Update minimum if this path is shorter
            minStepsFromHere = Math.min(minStepsFromHere, stepsForThisPath + 1);
        }

        // Second: try waiting in place (no movement, time increases by 1)
        int waitSteps = findPath(grid, row, col, time + 1, visited, rows, cols);
        minStepsFromHere = Math.min(minStepsFromHere, waitSteps + 1);

        // Return the shortest path length from this state
        return minStepsFromHere;
    }
}
```

