public class PairCounter {

    // Public wrapper method for user calls
    public static int countPairs(int[] arr) {
        return countPairsRecursive(arr, 0);
    }

    // Private recursive helper to track current index
    private static int countPairsRecursive(int[] arr, int index) {
        // Corrected base case: stop when no more pairs can be formed
        if (index >= arr.length - 1) {
            return 0;
        }

        // Check current pair (condition is logically valid as written)
        int currentCount = (arr[index] == 2 * arr[index + 1]) ? 1 : 0;

        // Recurse on the next index and accumulate total count
        return currentCount + countPairsRecursive(arr, index + 1);
    }

    public static void main(String[] args) {
